local cs_coroutine = require('XLua.cs_coroutine')

---@type ActivityCookingComponent
local ActivityCookingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityCookingComponent)



--- from: Assets/BundleResources/Prefabs/ActivityCakeShop/ActivityCakeShopFightRankingsDialog.prefab > name: ActivityCakeShopFightRankingsDialog
---@class ActionDarkDreamNewFunctionRankDialog
---@field Env                           	ActionDarkDreamNewFunctionRankDialog
---@field controller                    	Engine.UI.UILuaDialog
---@field LoopView                      	SuperScrollView.LoopListView2           	@ 0    
---@field EmptyNode                     	UnityEngine.RectTransform               	@ 1    
---@field LayoutListAndMyselef          	UnityEngine.RectTransform               	@ 2    
---@field MyRanking                     	UnityEngine.RectTransform               	@ 3    
---@field RewardPreviewButton           	UnityEngine.RectTransform               	@ 4    
local ActionDarkDreamNewFunctionRankDialog = Class("ActionDarkDreamNewFunctionRankDialog")

function ActionDarkDreamNewFunctionRankDialog:__init()

end

function ActionDarkDreamNewFunctionRankDialog:__delete()

end

function ActionDarkDreamNewFunctionRankDialog:Awake()
	SetButtonAction(self.RewardPreviewButton, Bind(self, self.ShowRewardPreviewWindow))
	SetButtonAction(self.BtnReward, Bind(self, self.OnBtnRewardClick))
	self.groupId = self.controller.Argument.parameters.groupId
	self.index = self.controller.Argument.parameters.index
end

function ActionDarkDreamNewFunctionRankDialog:OnShow()
	---@type Engine.Lib.CoWait
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
	
	end))
	return coWait
end

function ActionDarkDreamNewFunctionRankDialog:OnFocus()

end

function ActionDarkDreamNewFunctionRankDialog:OnInitialize()
	GameUtils.Request(Interfaces.OverseaNightRank,nil,function(request, response)
		if checkNumber(response.errCode) == 0 then
			self.rankData = response.data.rank
			self.myRank = response.data.playerRank
			self:RefreshShow()
		end
	end)
end

function ActionDarkDreamNewFunctionRankDialog:RefreshShow()
	if next(self.rankData) == nil then
		CfUtils.SetActive(self.LayoutListAndMyselef, false)
		CfUtils.SetActive(self.EmptyNode, true)
	else
		CfUtils.SetActive(self.LayoutListAndMyselef, true)
		CfUtils.SetActive(self.EmptyNode, false)
		
		self:RefreshLoopList()
		self:FillPlayerInfo()
	end
	self:RefreshRewardBtnState()
end

function ActionDarkDreamNewFunctionRankDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		
		self.controller = nil
		self:Delete()
		self = nil
	end))
	return coWait
end

function ActionDarkDreamNewFunctionRankDialog:RefreshLoopList()
	if not self.LoopView.IsListViewInit then
		self.LoopView:InitListView(#self.rankData, Bind(self, self.OnRefreshListIndex))
	else
		GameUtils.ReloadData(self.LoopView, #self.rankData)
	end
end

function ActionDarkDreamNewFunctionRankDialog:OnRefreshListIndex(listView, index)
	if index < 0 then
		return nil
	end
	
	local cell = listView:NewListViewItem("Cell")
	local data = {
		index = index,
		input = self.rankData[index + 1],
		groupId = self.groupId
	}
	
	local scr = CfUtils.GetLuaScr(cell, "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamNewFunctionRankCell")
	if scr then
		scr:Refresh(data)
	else
		printError("[UI][ActionDarkDreamNewFunctionRankDialog][OnRefreshListIndex] lua script Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamNewFunctionRankCell not found")
	end
	
	return cell
end

function ActionDarkDreamNewFunctionRankDialog:FillPlayerInfo()
	local scr = CfUtils.GetLuaScr(self.MyRanking, "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamNewFunctionRankCell")
	---@type PlayerDojo
	local playerDojo = GameUtils.GetPlayerDojo()
	
	local data = {}
	data.groupId = self.groupId
	data["input"] = {
		playerId=playerDojo.playerId,
		score=checkInt(self.myRank.damage),
		name=playerDojo.playerName,
		avatar=playerDojo.playerAvatar,
		avatarFrame=playerDojo.playerAvatarFrame,
		level=checkInt(playerDojo.level),
		ranking=checkInt(self.myRank.ranking),
	}
	
	if scr then
		scr:Refresh(data)
	end
end

function ActionDarkDreamNewFunctionRankDialog:ShowRewardPreviewWindow()
	UIModule.OpenDialog({id= Constants.UITypeIds.ActionDarkDreamRankRewardDialog,parameters = { autoId = AutoIds.IdSetting6606, rewardVos = self:GetRankVos() }})
end

function ActionDarkDreamNewFunctionRankDialog:GetRankVos()
	local data = {}
	local allVos = CfUtils.GetCf(AutoIds.IdSetting6606,"ChaoticRankRewardVo",true)
	for i, v in ipairs(allVos) do
		if v.groupId == checkNumber(self.groupId) then
			table.insert(data,v)
		end
	end
	return data
end

function ActionDarkDreamNewFunctionRankDialog:OnBtnRewardClick()
	local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
	local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
	local isGet = dojo:IsGetRankReward(self.index)
	if isGet then
		GameUtils.Toast(localize("奖励已领取"))
		return
	end
	
	GameUtils.Request(Interfaces.OverseaNightDrawRankReward,nil,function(request,response)
		if checkNumber(response.errCode) == 0 then
			dojo:UpdateRankRewardState(self.index, 1)
			self:RefreshRewardBtnState()
			Events.Broadcast("ActionDarkDreamMainDialogRefreshRedPoint")
			if table.count(response.data.rewards) > 0 then
				GoodsUtils.DrawRewards(response.data.rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = {
					rewards = response.data.rewards,} })
			end
		end
	end)
end

function ActionDarkDreamNewFunctionRankDialog:RefreshRewardBtnState()
	local isGet = self:IsGetRankReward()
	local redGo = GameUtils.GetRedPointGo(self.BtnReward)
	if isNotNull(redGo) then
		CfUtils.SetActive(redGo, not isGet)
	end
end

function ActionDarkDreamNewFunctionRankDialog:IsGetRankReward()
	local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
	local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
	local isGet = dojo:IsGetRankReward(self.index)
	return isGet
end

return ActionDarkDreamNewFunctionRankDialog